mapper.select:
SELECT rt.redpacket_t_id, rt.redpacket_t_type, rt.redpacket_t_title, rt.redpacket_t_desc, rt.redpacket_t_start_date, rt.redpacket_t_end_date, rt.redpacket_t_price, rt.redpacket_t_orderlimit, rt.redpacket_t_total, rt.redpacket_t_giveout, rt.redpacket_t_add_date, rt.redpacket_t_update_date, rt.redpacket_t_eachlimit, sp.user_id, sp.user_name, sp.user_avatar, sp.update_date, sg.gift_name, sg.gift_image, sg.gift_is_redpacket, pp.is_win, rt.redpacket_t_state, rb.redpacket_state FROM activity_spinwin_person sp LEFT JOIN activity_spinwin_prize pp ON sp.prize_id = pp.prize_id LEFT JOIN activity_spinwin_gift sg ON sg.gift_id = pp.gift_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_redpacket_base rb ON sp.redpacket_id = rb.redpacket_id LEFT JOIN ${database.prefix.activity}hou_addon_activity_redpacket_template rt ON rb.redpacket_t_id = rt.redpacket_t_id WHERE pp.activity_id = #{param.activityId}
and sp.user_id = #{param.userId}
order by sp.update_date desc,rt.redpacket_t_price DESC

SELECT count(1)
FROM activity_spinwin_person
WHERE activity_id = #{param.activityId}
  and user_id = #{param.userId}
